function practiceSection(data) {
 if(data.id===LESSON)return `<section class="card game-entry" id="practice"><span class="eyebrow" style="color:var(--lime)">02 / ТӘЖІРИБЕ АЛАҢЫ</span><h2>Қалашықты желіге қос.</h2><p>Желі орталығына кір: құрылғылардың қызметін анықта, екі компьютерді байланыстыр және интернетке шығуға не кедергі болғанын зертте.</p><a class="primary" href="/game/?lesson=${LESSON}">3D кампусқа өту ↗</a><p class="hint" style="color:#c1cfbf;margin-top:15px">Ойын жүктелмесе, төмендегі дәл сол тапсырманың мәтіндік нұсқасын орында.</p><details><summary>Ойынсыз орындау</summary><form id="fallback-form" style="margin-top:20px"><div class="form-message"></div><p>Мақсат: екі компьютерді ортақ жергілікті желіге қосып, сыртқы желіге шығуын қамтамасыз ету. Құрылғылардың қызметін және қажетті байланыстарды өзің таңда.</p>${['node','switch','router'].map((key,i)=>`<div class="field"><label for="role-${key}">${['Торап (node)','Коммутатор (switch)','Маршрутизатор (router)'][i]}</label><select id="role-${key}" name="${key}" required><option value="">Қызметті таңдаңыз</option value="local">Жергілікті құрылғыларды байланыстыру</option><option value="networks">Желілерді байланыстыру</option><option value="endpoint">Соңғы құрылғы</option></select></div>`).join('')}<fieldset style="border:1px solid #718470;border-radius:10px;margin:0 0 18px"><legend>Қажетті байланыстарды таңдаңыз</legend>${[['pc1','switch'],['pc2','switch'],['switch','router'],['pc1','router']].map((link,i)=>`<label style="display:block"><input type="checkbox" name="link" value="${i}"> ${link.map(esc).join(' ↔ ')}</label>`).join('')}</fieldset><div class="field"><p class="diagnostic-evidence"><b>Бақылау:</b> екі компьютер жергілікті желіде хабарласады, бірақ интернетке шыға алмайды. Тексеру сызбасында маршрутизаторға баратын кабельдің бір ұшы портқа жалғанбаған. Осы дәлелге сүйеніп диагноз қой.</p><label for="fault">Интернетке шығуға не кедергі болған?</label><select id="fault" name="fault" required><option value="">Себебін таңдаңыз</option value="cable">Кабель ажыратылған</option><option value="screen">Экран жарықтығы төмен</option><option value="keyboard">Пернетақта қосылмаған</option></select></div><button class="primary">Практиканы тексеру</button><div id="criteria" aria-live="polite"></div></form></details></section>`;
 const game=safeURL(data.gameUrl),assessment=data.kind==='assessment';
 return `<section class="card game-entry" id="practice"><span class="eyebrow">02 / ${assessment?'БАҒАЛАУ ЖҰМЫСЫ':'ПРАКТИКА'}</span><h2>${assessment?'Біліміңді көрсет.':'Біліміңді тәжірибеде сына.'}</h2><p>${assessment?'Материалдардағы бағалау тапсырмасын орында. Жұмысты мұғалім тексереді; рефлексия автоматты баға болып саналмайды.':game?'Осы сабақтың практика кеңістігін ашып, нұсқаулық бойынша орында.':'Сабақ материалдарындағы практикалық тапсырмаларды орында. Бұл сабаққа жеке ойын сілтемесі берілмеген.'}</p>${game&&!assessment?`<a class="primary" href="${esc(game)}">Практика кеңістігін ашу ${icon('arrow-right')}</a>`:''}${isStaff()?'<p class="note">Қызметкердің алдын ала қарау режимі. Оқушының рефлексиясын жібермей, материал мен миссияны тексеруге болады.</p>':''}</section>`;
}
function summaryContent(text) {
 const match=text.match(/<!doctype html>[\s\S]*?<\/html>/i);if(!match)return `<p class="lesson-summary">${esc(text)}</p>`;
 const before=text.slice(0,match.index),after=text.slice(match.index+match[0].length).replace(/Тақырыппен таныстым\s*Презентацияға өту\s*→?/g,'').trim();
 return `<p class="lesson-summary">${esc(before)}</p><pre class="code-sample"><code>${esc(match[0].replace(/>\s*</g,'>\n<'))}</code></pre>${after?`<p class="lesson-summary">${esc(after)}</p>`:''}`;
}
